#define WIN32_LEAN_AND_MEAN
#define NOMINMAX
#include <windows.h>
#include <cstdio>
#include <cstdint>
#include <cstring>
#include <string>
#include <stdexcept>

std::string quote(const char* text) {
    std::string value = "\"";
    for (const unsigned char* p = reinterpret_cast<const unsigned char*>(text); *p; ++p) {
        if (*p == '\\' || *p == '"') value += '\\';
        if (*p >= 32) value += static_cast<char>(*p);
        else value += '?';
    }
    return value + '"';
}
template<class... Args>
std::uint32_t call(HMODULE module, const char* name, Args... args) {
    using Function = std::uint32_t (__stdcall*)(Args...);
    const auto address = GetProcAddress(module, name);
    if (!address) throw std::runtime_error(std::string("Missing installed FMOD export: ") + name);
    Function function;
    std::memcpy(&function, &address, sizeof function);
    return function(args...);
}
int main() {
    static_assert(sizeof(void*) == 4);
    const wchar_t* core_path = L"I:\\SteamLibrary\\steamapps\\common\\Battlestations Pacific\\fmodex.dll";
    const wchar_t* event_path = L"I:\\SteamLibrary\\steamapps\\common\\Battlestations Pacific\\fmod_event.dll";
    HMODULE core = LoadLibraryExW(core_path, nullptr, LOAD_WITH_ALTERED_SEARCH_PATH);
    HMODULE events = LoadLibraryExW(event_path, nullptr, LOAD_WITH_ALTERED_SEARCH_PATH);
    if (!core || !events) { std::printf("{\"load_error\":%lu}\n", GetLastError()); return 2; }
    char actual_core[MAX_PATH]{}, actual_events[MAX_PATH]{};
    GetModuleFileNameA(core, actual_core, MAX_PATH);
    GetModuleFileNameA(events, actual_events, MAX_PATH);
    std::printf("{\"step\":\"process\",\"pid\":%lu,\"pointer_bits\":32,\"actual_core\":%s,\"actual_event\":%s}\n",
        GetCurrentProcessId(), quote(actual_core).c_str(), quote(actual_events).c_str());
    void* event = nullptr;
    void* system = nullptr;
    auto result = call(events, "_FMOD_EventSystem_Create@4", &event);
    std::printf("{\"step\":\"EventSystem_Create\",\"result\":%u,\"object_returned\":%s}\n", result, event ? "true" : "false");
    if (result || !event) return 3;
    result = call(events, "_FMOD_EventSystem_GetSystemObject@8", event, &system);
    std::printf("{\"step\":\"EventSystem_GetSystemObject\",\"result\":%u,\"object_returned\":%s}\n", result, system ? "true" : "false");
    if (!result && system) {
        unsigned version = 0xffffffffu;
        result = call(core, "FMOD_System_GetVersion", system, &version);
        std::printf("{\"step\":\"System_GetVersion\",\"result\":%u,\"output_valid\":%s,\"observed\":%u}\n", result, result ? "false" : "true", version);
        int output = -1;
        result = call(core, "FMOD_System_GetOutput", system, &output);
        std::printf("{\"step\":\"System_GetOutput_before_init\",\"result\":%u,\"output_valid\":%s,\"observed\":%d}\n", result, result ? "false" : "true", output);
        int count = 0;
        result = call(core, "FMOD_System_GetNumDrivers", system, &count);
        std::printf("{\"step\":\"System_GetNumDrivers\",\"result\":%u,\"output_valid\":%s,\"observed\":%d}\n", result, result ? "false" : "true", count);
        int minimum = 0, maximum = 0, speaker = 1;
        if (count >= 0 && count <= 256) {
            for (int index = count - 1; index >= 0; --index) {
                char name[1024]{};
                GUID driver_guid{};
                const auto name_result = call(core, "FMOD_System_GetDriverInfo", system, index, name, int(sizeof name), &driver_guid);
                name[sizeof name - 1] = 0;
                std::printf("{\"step\":\"System_GetDriverInfo_diagnostic\",\"index\":%d,\"result\":%u,\"output_valid\":%s,\"name\":%s}\n",
                    index, name_result, name_result ? "false" : "true", name_result ? "null" : quote(name).c_str());
                unsigned caps = 0;
                result = call(core, "FMOD_System_GetDriverCaps", system, index, &caps, &minimum, &maximum, &speaker);
                std::printf("{\"step\":\"System_GetDriverCaps\",\"index\":%d,\"result\":%u,\"output_valid\":%s,\"caps_observed\":%u,\"min_frequency_observed\":%d,\"max_frequency_observed\":%d,\"speaker_observed\":%d}\n",
                    index, result, result ? "false" : "true", caps, minimum, maximum, speaker);
            }
            result = call(core, "FMOD_System_SetSpeakerMode", system, speaker);
            std::printf("{\"step\":\"System_SetSpeakerMode\",\"argument\":%d,\"result\":%u}\n", speaker, result);
            result = call(events, "_FMOD_EventSystem_Init@20", event, int(512), unsigned(16), static_cast<void*>(nullptr), unsigned(0));
            std::printf("{\"step\":\"EventSystem_Init\",\"max_channels\":512,\"init_flags\":16,\"extra_driver_data\":null,\"event_init_flags\":0,\"result\":%u}\n", result);
            int driver = -1;
            result = call(core, "FMOD_System_GetDriver", system, &driver);
            std::printf("{\"step\":\"System_GetDriver_after_init\",\"result\":%u,\"output_valid\":%s,\"observed\":%d}\n", result, result ? "false" : "true", driver);
            output = -1;
            result = call(core, "FMOD_System_GetOutput", system, &output);
            std::printf("{\"step\":\"System_GetOutput_after_init\",\"result\":%u,\"output_valid\":%s,\"observed\":%d}\n", result, result ? "false" : "true", output);
            speaker = -1;
            result = call(core, "FMOD_System_GetSpeakerMode", system, &speaker);
            std::printf("{\"step\":\"System_GetSpeakerMode_after_init\",\"result\":%u,\"output_valid\":%s,\"observed\":%d}\n", result, result ? "false" : "true", speaker);
        }
    }
    result = call(events, "_FMOD_EventSystem_Release@4", event);
    std::printf("{\"step\":\"EventSystem_Release_owns_core_system\",\"result\":%u}\n", result);
    FreeLibrary(events);
    FreeLibrary(core);
    return 0;
}

